package com.tallerzapata.backend.infrastructure.persistence.cleasstate;
import jakarta.persistence.*;
import java.time.LocalDateTime;
@Entity @Table(name="cleas_effective_state_history")
public class CleasEffectiveStateHistoryEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="caso_id") private Long caseId; @Column(name="prior_tramite_codigo") private String priorProcedureCode; @Column(name="new_tramite_codigo") private String newProcedureCode; @Column(name="prior_reparacion_codigo") private String priorRepairCode; @Column(name="new_reparacion_codigo") private String newRepairCode; private String cause; @Column(name="actor_usuario_id") private Long actorUserId; private String reason; @Column(name="override_dimension") private String overrideDimension; @Column(name="override_prior_codigo") private String overridePriorCode; @Column(name="override_new_codigo") private String overrideNewCode; @Column(name="created_at") private LocalDateTime createdAt; public void setCaseId(Long v){caseId=v;} public void setPriorProcedureCode(String v){priorProcedureCode=v;} public void setNewProcedureCode(String v){newProcedureCode=v;} public void setPriorRepairCode(String v){priorRepairCode=v;} public void setNewRepairCode(String v){newRepairCode=v;} public void setCause(String v){cause=v;} public void setActorUserId(Long v){actorUserId=v;} public void setReason(String v){reason=v;} public void setOverrideDimension(String v){overrideDimension=v;} public void setOverridePriorCode(String v){overridePriorCode=v;} public void setOverrideNewCode(String v){overrideNewCode=v;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
